// B-015: one ScrollController shared by the folder + search-results ListViews
// (mutually exclusive, so no conflict). The per-track GlobalKeys (KeyedSubtree
// wrappers) give Scrollable.ensureVisible a stable target across rebuilds.
final scroll = useScrollController();
final rowKeys = useRef(<String, GlobalKey>{}).value;

// Bump a cheap recheck after the first layout pass + after scrolling stops.
// Our now-playing action uses per-row GlobalKey contexts; those contexts
// can become non-null one frame after scroll ends.
final visibilityRecheckTick = useState(0);
useEffect(() {
  WidgetsBinding.instance.addPostFrameCallback((_) {
    if (context.mounted) visibilityRecheckTick.value++;
  });

  ValueNotifier<bool>? notifier;
  VoidCallback? listener;
  var attached = false;

  void tryAttach() {
    if (attached || !scroll.hasClients) return;
    notifier = scroll.position.isScrollingNotifier;
    listener = () {
      if (notifier == null || notifier!.value) return;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (context.mounted) visibilityRecheckTick.value++;
      });
    };
    notifier!.addListener(listener!);
    attached = true;
  }

  tryAttach();
  WidgetsBinding.instance.addPostFrameCallback((_) => tryAttach());

  return () {
    if (attached && notifier != null && listener != null) {
      notifier!.removeListener(listener!);
    }
  };
}, [scroll]);
